export const PRODUCT = {

omniscripts: {
  packages: ["omnistudio"],
  name: "OmniScripts",
  icon: "\u{1FA84}",
  color: "#a78bfa",
  description: "OmniStudio Omniscripts provide declarative, multi-step interactions that display information, collect and validate user input, perform calculations, and submit data. They use formula functions, call Data Mappers and Integration Procedures, and can embed Flexcards or custom Lightning web component elements. Runtime execution can read Omni Interaction Configuration settings, while preview and test tools validate behavior and OmniAnalytics tracks user interactions. Activated Omniscripts can run on Lightning and Experience Cloud pages, be exposed as Agentforce actions, and be exported through DataPacks for deployment.",
  components: [
    {id:"os-designer",name:"OmniScript Designer",icon:"\u{1F3A8}",desc:"The OmniScript Designer is OmniStudio’s declarative environment for creating guided interactions with clicks instead of code. Designers drag input, display, group, formula, and action elements onto a canvas and configure their properties to match a business process. The designer also supports preview, testing, styling, version management, and activation of Omniscripts.",tags:["OmniProcess","OmniProcessElement"],docs:["Use the OmniScript Designer to arrange elements into a guided, step-by-step interaction. Elements can collect user input, display information, perform calculations, invoke actions, and create branches that adjust controls or enable and disable steps based on user choices. Templates and design settings control presentation options such as branding and horizontal or vertical navigation.","The standard designer lets users drag elements to the canvas and edit their properties without switching between tabs. The Newport Design System provides real-time previews with Lightning, Newport, and Newport Storybook themes, although Newport Storybook is available only in designer preview. Designers can override default styles and use centralized styling resources to maintain consistent branding.","Preview and test an Omniscript before activation to validate its behavior and user experience. An Omniscript can include Flexcards for data visualization and custom Lightning web component elements for specialized interfaces. After activation, it can be placed on supported Lightning or Experience Cloud pages or launched from actions and links."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_designers_common.htm&type=5",connections:[{"planet":"flexcards","desc":"OmniScripts launch FlexCards as embedded displays"},{"planet":"integration","desc":"OmniScripts invoke Integration Procedures for server-side logic"},{"planet":"datamappers","desc":"OmniScripts use Data Mappers for data read and write operations"},{"planet":"formulas","desc":"OmniScripts evaluate formula expressions in SetValues and calculations"},{"planet":"lwc","desc":"OmniScripts host custom LWC elements in the designer palette"}]},
    {id:"os-input-elements",name:"Input Elements",icon:"\u{1F4DD}",desc:"Input Elements collect information from users as they move through an OmniStudio Omniscript. They support guided response formats such as text, radio-button choices, and lookups. Input values become part of the Omniscript’s runtime Data JSON and can influence validation, calculations, conditional branches, and subsequent actions.",tags:["OmniProcessElement"],docs:["Add input fields and lookups when users must enter or select information during a guided process. For example, an Omniscript questionnaire can collect medical history, vehicle details, prior claims, or other information across several screens. The selected input type determines how the user supplies the value.","Configure calculations and messages to provide immediate feedback and error checking for entered values. User responses can also drive conditional logic that changes which controls, actions, or steps are available. The collected values remain available in Data JSON for formulas, merge fields, and downstream data operations."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omniscipts_customize_behavior_style.htm&type=5",connections:[]},
    {id:"os-display-elements",name:"Display & Formula Elements",icon:"\u{1F4CA}",desc:"Display & Formula Elements present explanatory content and calculate values within an OmniStudio Omniscript. Display elements such as headlines and text blocks refine the guided experience without requiring user input. Formula elements use supported OmniStudio formulas and functions to evaluate runtime data and support dynamic feedback or branching.",tags:["OmniProcessElement"],docs:["Use display elements to provide headings, instructions, messages, and other information alongside interactive controls. Omniscripts can also embed Flexcards when the process requires a richer visualization of contextual data. Templates, themes, and element styling determine how this content appears to users.","Use formulas to calculate or manipulate values available to the Omniscript. Formula results can contribute to immediate feedback, error checking, and conditional behavior based on user choices or retrieved data. Merge fields can reference values at paths in Data JSON so that displayed content and configured properties reflect runtime information."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omnistudio_formulas_and_functions.htm&type=5",connections:[{"planet":"formulas","desc":"Display elements use formula functions for computed values"}]},
    {id:"os-action-elements",name:"Action Elements",icon:"\u{26A1}",desc:"Action Elements connect an OmniStudio Omniscript to data operations and other processing. Actions can retrieve or submit data, send email, call Data Mappers, invoke Integration Procedures, access REST endpoints, or invoke supported Apex implementations. Their responses can be added to Data JSON for use by later elements in the guided process.",tags:["OmniProcessElement","OmniProcess"],docs:["Use Data Mapper actions for declarative Salesforce data access, loading, or transformation. Invoke an Integration Procedure when the process requires reusable server-side orchestration across multiple data operations or source types. Omniscripts can also call REST endpoints and Apex methods, including remote actions implemented through the Salesforce Callable interface.","Other supported action scenarios include sending email and working with DocuSign envelopes. Configure action inputs from current Data JSON values and use returned data in subsequent steps, formulas, or display elements. Access to Apex remote actions can be governed by the ApexClassCheck Omni Interaction Configuration setting and the user’s permissions.","Place supported actions in an Action Block when several tasks should run in parallel. An Action Block supports up to four actions and provides default, non-blocking, or fire-and-forget execution behavior. Use this grouping only where the actions and the required execution behavior fit the guided process."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_navigate_action_12710.htm&type=5",connections:[{"planet":"integration","desc":"Action elements execute Integration Procedures"},{"planet":"datamappers","desc":"Action elements invoke Data Mapper operations"},{"planet":"config","desc":"Action elements reference e-signature and interaction configurations"}]},
    {id:"os-groups",name:"Step & Group Elements",icon:"\u{1F4C2}",desc:"Step & Group Elements organize an OmniStudio Omniscript into pages and related sections. Steps present successive screens in the guided process, while Blocks group elements and create nested structures in Data JSON. Specialized group elements support repeatable entries and grouped action execution.",tags:["OmniProcessElement"],docs:["Use Steps to divide a complex interaction into a sequence of manageable screens. Navigation can be presented horizontally or vertically according to the selected template and configuration. Conditional branches can enable, disable, show, or bypass parts of the process based on user choices.","Use a Block to group related controls and values under a nested Data JSON node. A Block can repeat when the process must capture an array of similar entries. This organization keeps related information together for formulas and downstream actions.","Use an Edit Block when users must add, edit, or delete multiple entries and optionally map those entries to Salesforce records. Use an Action Block to run up to four supported actions in parallel with its configured execution behavior. These group elements structure either user-managed collections or coordinated processing within the Omniscript."],connections:[]},
    {id:"os-sessions",name:"Saved Sessions & Resume",icon:"\u{1F4BE}",desc:"Saved Sessions & Resume support OmniStudio Omniscripts that users cannot finish in one interaction. Save-for-later behavior persists the current data and page so the user can resume the guided process. Saved-session access depends on the user or guest-user permissions configured for Omniscript Saved Session records.",tags:["OmniscriptSavedSession","OmniProcessTransientData"],docs:["A saved session retains an Omniscript’s DataPayload together with its associated OmniProcessId, UserId, Status, and LastSavedPage. The saved page and payload allow the process to restore the user’s progress instead of beginning again. CreatedDate and ExpirationDate provide timing information for the stored session.","The OmniStudio User permission set grants create, read, update, and delete access to Omniscript Saved Session records. Guest-user configurations can be adjusted when public-facing experiences require Save for Later, while object and field access must still be explicitly granted. Standard runtime enforces field-level security, so access to Omniscript Saved Sessions must be verified when configuring runtime permissions."],connections:[]},
    {id:"os-compilation",name:"Activation & Compilation",icon:"\u{2699}",desc:"Activation & Compilation prepare an OmniStudio Omniscript for runtime use while preserving versioned definitions for controlled changes. Activation marks the version that consumers can run, and compilation records track compiled Omniscripts where compilation applies. Runtime behavior differs between the standard runtime and the managed package runtime.",tags:["OmniProcessCompilation","OmniProcess"],docs:["Preview and test an Omniscript before activating the intended version. In the standard runtime, activated custom content runs through the standard Omniscript component and activation doesn’t generate a separate LWC. Add the standard component to a Lightning page or supported Experience Cloud page after activation.","In the managed package runtime, activation generates an Omniscript Lightning web component. Existing generated components can transition to the standard runtime when managed package runtime is disabled and the content is reactivated. Omni Process Compilation records represent compiled Omniscripts and Integration Procedures and require appropriate read and field-level access.","Create a new version when modifying standard content supplied with a Salesforce Industries license because its Version 1 is not editable. Release updates are applied to Version 1 and do not update versions created by customers. OmniStudio components can also be packaged in DataPacks for deployment between environments, while Salesforce CLI is recommended for deployments using standard runtime and standard objects."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_enable_standard_omnistudio_runtime.htm&type=5",connections:[{"planet":"deployment","desc":"Compiled OmniScripts are packaged in DataPacks for migration"},{"planet":"testing","desc":"Compiled OmniScripts are validated in preview and test frameworks"}]}
  ],
  dataFlow: ["Design the guided flow with Steps, groups, inputs, displays, formulas, embedded Flexcards, and custom LWC elements.","Read Omni Interaction Configuration settings and retrieve or write process data through Data Mappers.","Invoke Integration Procedures and other configured actions for reusable server-side processing.","Preview and test the Omniscript, then activate the required version for its target runtime.","Embed the activated Omniscript on Lightning or Experience Cloud pages, or expose it as an Agentforce action.","Track interactions with OmniAnalytics, persist resumable sessions when configured, and export the Omniscript through DataPacks for deployment."],
  connections: [{"planet":"flexcards","desc":"OmniScripts embed FlexCards for data display"},{"planet":"integration","desc":"OmniScripts invoke Integration Procedures for server logic"},{"planet":"datamappers","desc":"OmniScripts call Data Mappers for data read/write"},{"planet":"formulas","desc":"OmniScripts use formula functions in calculations"},{"planet":"analytics","desc":"OmniScript interactions are tracked for analytics"},{"planet":"testing","desc":"OmniScripts are validated in preview and test tools"},{"planet":"agentforce","desc":"OmniScripts are exposed as Agentforce actions"},{"planet":"experience","desc":"OmniScripts are embedded in Experience Cloud pages"},{"planet":"config","desc":"OmniScripts read interaction configuration settings"},{"planet":"deployment","desc":"OmniScripts are exported via DataPacks"},{"planet":"lwc","desc":"OmniScripts host custom LWC elements"}]
},

flexcards: {
  packages: ["omnistudio"],
  name: "FlexCards",
  icon: "\u{1F5C2}",
  color: "#f472b6",
  description: "Flexcards are OmniStudio’s declarative UI components for displaying contextual information and launching relevant actions on the Salesforce platform. They retrieve data through sources such as Integration Procedures and Data Mapper queries, render conditional states, support child cards and custom Lightning Web Components, and can launch Omniscripts or provide context for agent actions. Flexcards can be embedded in Omniscripts as display elements or placed on Lightning and Experience Cloud pages. Designers preview and test cards with built-in preview and UTAM, then activate and deploy them through supported DataPack or Salesforce CLI workflows.",
  components: [
    {id:"fc-designer",name:"FlexCard Designer",icon:"\u{1F3A8}",desc:"The FlexCard Designer is OmniStudio’s declarative environment for creating contextual UI components without code. Designers drag elements onto a WYSIWYG canvas, edit their properties, and configure layouts, styling, data, conditions, and actions. Flexcards can be previewed and debugged before activation, then published for use on Lightning and Experience Cloud pages. The generated Flexcard runs as a Lightning Web Component.",tags:["OmniUiCard"],docs:["The FlexCard Designer provides a drag-based canvas for assembling customer-centric interfaces from configurable elements. In the OmniStudio standard designer, designers can drag elements to the canvas and edit their properties at the same time without switching between tabs. The designer supports creating, managing, previewing, and optimizing Flexcards through a declarative workflow focused on business logic rather than programming.","Designers can style individual elements, add custom CSS directly to an element, and make elements responsive. A Flexcard can combine pertinent information with links and actions that are relevant to a specific customer or business context. The Newport Design System also supports consistent branding and style overrides for OmniStudio components, including Flexcards.","Preview and debug the Flexcard before activating and publishing it. Flexcards can also be tested through the UI Test Automation Model framework for end-to-end UI automation. When using the standard designer, validate a new component version before activating it for Lightning or Experience Cloud sites, because components opened in the standard designer can no longer be edited in the managed package designer."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_set_up_a_flexcard_in_the_flexcard_designer_37646.htm&type=5",connections:[{"planet":"omniscripts","desc":"FlexCards launch OmniScripts from action buttons"},{"planet":"integration","desc":"FlexCards invoke Integration Procedures as data sources"},{"planet":"lwc","desc":"FlexCards embed custom LWC components for extended functionality"}]},
    {id:"fc-datasources",name:"Data Sources",icon:"\u{1F50C}",desc:"Data Sources connect Flexcards to contextual information from Salesforce and external systems. A Flexcard can bind to Integration Procedures, Data Mapper queries, SOQL queries, Apex, or REST APIs according to the selected source configuration. Integration Procedures support multistep processing across source types, while Data Mappers declaratively retrieve Salesforce object data. Runtime context can be supplied through Flexcard context variables.",tags:["OmniUiCard"],docs:["Configure a data source to retrieve the information displayed by a Flexcard. Flexcards can pull data from multiple sources and use the returned values in their fields, elements, conditions, and actions. Context variables such as recordId, Parent, Session, User, record, or action provide runtime values that can be passed to data sources or referenced by card configurations.","Use an OmniStudio Data Mapper when the requirement is to read mapped data from related Salesforce objects or perform a supported single-step transformation. Use an Integration Procedure when retrieval requires multiple operations, multiple source types, REST APIs, Apex classes, conditional processing, or reusable server-side orchestration. Integration Procedures commonly call one or more Data Mappers and return prepared data to the Flexcard.","Configure and test the source response before publishing the card so that the layout and conditions use the expected data structure. Standard runtime enforces field-level security more strictly than managed package runtime, so users must have the necessary object and field access. Remote actions that call Apex also require explicit access to the Apex class when the applicable OmniStudio security check is enabled."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_configure_a_data_source_on_a_flexcard_35864.htm&type=5",connections:[{"planet":"integration","desc":"Data sources invoke Integration Procedures for complex data assembly"},{"planet":"datamappers","desc":"Data sources use Data Mappers for Salesforce data queries"}]},
    {id:"fc-states",name:"Card States & Conditions",icon:"\u{1F504}",desc:"Card States & Conditions control which Flexcard presentation is shown for the current data and context. A Flexcard can define multiple states whose conditions determine the fields, elements, and actions visible to a user. Conditional logic can also show or hide individual elements without requiring a multistep interaction. This supports concise, context-specific presentations of customer and business information.",tags:["OmniUiCard"],docs:["Define states to vary a Flexcard’s layout and available interactions according to data conditions. Each state can present a different combination of fields, elements, and actions for the current record or returned data. This lets one card respond dynamically to context while remaining focused on displaying information and supporting simple interactions.","Use conditional display rules when only particular elements must be shown or hidden. Conditions can reference values supplied by the configured data source or runtime context. Preview the Flexcard with representative source data to verify that the intended state and conditional elements appear before activation."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_add_conditions_to_a_flexcard_element_35370.htm&type=5",connections:[]},
    {id:"fc-actions",name:"Actions & Flyouts",icon:"\u{1F3AF}",desc:"Actions & Flyouts make Flexcards interactive while keeping information within the customer’s current context. Actions can launch or update an Omniscript, navigate to a web page or application, display a flyout, fire an event, or update field values. A flyout can present an Omniscript, child Flexcard, or custom Lightning Web Component in a modal or popover. Flexcards can also provide contextual surfaces from which users invoke agent actions.",tags:["OmniUiCard","OmniProcess"],docs:["Configure actions on a Flexcard to connect displayed information with the next business task. Supported uses include launching or updating an Omniscript, navigating to another page or application, firing an event, updating field values, and displaying a flyout. For example, an account card can provide actions to close a case, open a case, or create a task.","Use an Omniscript action when the next task requires a guided, step-by-step process. A flyout keeps supplementary content near the card by presenting an Omniscript, child Flexcard, or custom Lightning Web Component in a modal or popover. These patterns let a Flexcard remain a compact context surface while delegating more complex interactions to another OmniStudio component.","Configure each action with the runtime context and data required by its target. Flexcard event listeners can respond to pubsub, custom, or record-change events and run one or more actions. Preview and test actions before activation to confirm that navigation, events, flyouts, and launched components use the intended context."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_add_an_action_to_a_flexcard_25672.htm&type=5",connections:[{"planet":"omniscripts","desc":"Actions launch OmniScripts as modals or inline guided processes"},{"planet":"agentforce","desc":"FlexCard actions integrate with Agentforce workflows"}]},
    {id:"fc-child-cards",name:"Child Cards & Embedding",icon:"\u{1F4E6}",desc:"Child Cards & Embedding support modular Flexcard compositions and placement within broader OmniStudio experiences. Parent Flexcards can reference active child Flexcards to reuse focused presentations of related data and actions. Flexcards can also host custom Lightning Web Components and can be embedded in Omniscripts as display elements. Activated cards can be placed on Lightning and Experience Cloud pages.",tags:["OmniUiCard"],docs:["Use child Flexcards to divide a larger interface into reusable card units. Create and test child Flexcards before configuring the parent, because a child Flexcard must be active before the parent can reference it. The parent’s configuration retains the child-card references used by the composition.","Flexcards can be added to Lightning or Experience Cloud pages after activation. Standard OmniStudio content can be placed with the standard Flexcard component in Lightning App Builder or Experience Builder, subject to the selected runtime. Flexcards can also be embedded in Omniscripts as display elements when a guided process needs a contextual visualization of data.","A Flexcard can include a custom Lightning Web Component when the declarative elements don’t provide the required presentation. Generated Flexcards are themselves Lightning Web Components and can be modified when business logic requires customization. For an LWR Experience site, the documented embedding approach requires the managed package runtime setting to remain enabled and uses the generated LWC."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_embed_flexcards_in_an_omniscript_24124.htm&type=5",connections:[{"planet":"experience","desc":"Composed FlexCards are placed on Experience Cloud pages"}]}
  ],
  dataFlow: ["Configure Flexcard data retrieval through Integration Procedures, Data Mapper queries, or other supported sources.","Compose the layout, conditional states, child cards, and any hosted custom Lightning Web Components.","Add actions that launch Omniscripts, open flyouts, navigate, fire events, update values, or support agent actions.","Preview and debug the Flexcard, then automate applicable end-to-end checks with UTAM.","Activate the Flexcard and place it on Lightning or Experience Cloud pages, or embed it in an Omniscript as a display element.","Export supported Flexcards through DataPacks for deployment; use Salesforce CLI where the standard designer workflow requires it."],
  connections: [{"planet":"omniscripts","desc":"FlexCards are embedded in OmniScripts as display elements"},{"planet":"integration","desc":"FlexCards use Integration Procedures as data sources"},{"planet":"datamappers","desc":"FlexCards read data through Data Mapper queries"},{"planet":"testing","desc":"FlexCards are tested with preview and UTAM framework"},{"planet":"agentforce","desc":"FlexCards serve as context surfaces for agent actions"},{"planet":"experience","desc":"FlexCards are placed on Experience Cloud pages"},{"planet":"deployment","desc":"FlexCards are exported via DataPacks"},{"planet":"lwc","desc":"FlexCards host custom LWC components"}]
},

integration: {
  packages: ["omnistudio"],
  name: "Integration Procedures",
  icon: "\u{1F5A7}",
  color: "#38bdf8",
  description: "Integration Procedures are OmniStudio server-side processes that combine data operations, transformations, callouts, business rules, and supporting actions into reusable multistep transactions without an end-user UI. They commonly invoke Data Mappers, REST endpoints, Apex classes, Decision Matrices, and Expression Sets while using formulas, blocks, caching, and error handling to control execution. Integration Procedures provide backend logic for Omniscripts, serve as data sources for Flexcards, respect Omni Interaction Configuration and runtime security, and can be exported through DataPacks for deployment.",
  components: [
    {id:"ip-designer",name:"IP Designer",icon:"\u{1F3A8}",desc:"IP Designer is the declarative environment for building server-side Integration Procedures in OmniStudio. Designers arrange actions and blocks into a multistep process that can work with Salesforce data, REST APIs, Apex classes, and other Integration Procedures. The resulting process has no end-user UI and can run synchronously or asynchronously for reuse by callers such as Omniscripts and Flexcards.",tags:["OmniProcess","OmniProcessElement"],docs:["An Integration Procedure bundles server-side data integration operations for efficiency and reuse. Use it when a process must read from and write to Salesforce, work with unrelated objects, combine multiple data-source types, or perform transformations that require more than direct mappings and formulas. Integration Procedures can also send email, merge lists, and handle errors.","The standard designer provides a canvas for inserting, editing, rearranging, and connecting actions and blocks. Its layout supports element search and left-to-right drag-and-drop configuration, and Integration Procedure settings are available directly from the designer. Save after each edit so that the change takes effect.","An Integration Procedure is identified for invocation by its Type and SubType joined with an underscore. Type and SubType can contain letters, numbers, and special characters, but not spaces. After building the process, test its behavior and activate the intended version before making it available to runtime callers."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_designers_common.htm&type=5",connections:[{"planet":"omniscripts","desc":"OmniScripts invoke Integration Procedures for backend processing"},{"planet":"flexcards","desc":"FlexCards use Integration Procedures as data sources"},{"planet":"config","desc":"IP execution respects interaction configuration settings"}]},
    {id:"ip-data-actions",name:"Data Actions",icon:"\u{1F4C0}",desc:"Data Actions connect an Integration Procedure to reusable OmniStudio Data Mapper operations and other data-processing steps. An Integration Procedure commonly invokes one or more Data Mappers when it must retrieve, write, or transform data across multiple stages. These actions let the procedure coordinate data access with subsequent branching, callouts, list processing, and response construction.",tags:["OmniProcess","OmniDataTransformation"],docs:["Use Data Mapper actions to incorporate declarative Salesforce data access and transformation into an Integration Procedure. Multiple Data Mappers can be called when a process must both read and write records or work with Salesforce objects that don't have a defined relationship. A single Integration Procedure can combine these operations with REST, Apex, external-object, or other supported data sources.","Pass the required input data to each operation and use its returned data in later actions or blocks. Formula expressions can filter, calculate, or reformat values, while the Integration Procedure controls whether and when those transformations run. This approach supports multistep JSON processing when direct input-to-output node mappings aren't sufficient.","Apply the security configuration required for the invoked Data Mappers and Integration Procedure. Standard runtime enforces field-level security more strictly than managed package runtime, so users require appropriate access to the affected objects and fields. Required permissions and applicable Omni Interaction Configuration settings also govern runtime access."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_manipulate_json_with_the_send_response_transformations_properties_22367.htm&type=5",connections:[{"planet":"datamappers","desc":"Data actions invoke Data Mapper definitions for CRUD operations"}]},
    {id:"ip-http-remote",name:"HTTP & Remote Actions",icon:"\u{1F310}",desc:"HTTP & Remote Actions let Integration Procedures exchange data with REST endpoints and invoke Apex implementations. These server-side actions enable a procedure to combine Salesforce operations with external services or custom application logic. Remote Actions support Apex classes that implement the Salesforce Callable interface.",tags:["OmniProcess"],docs:["Use HTTP actions when an Integration Procedure must read from or write to a REST API as part of a multistep integration. Returned data can be processed by later actions, transformations, conditions, or response logic. Because Integration Procedures run without an end-user UI, they can centralize these callouts for reuse by multiple calling components.","Use Remote Actions to invoke an Apex class and method with configured additional input. OmniStudio Remote Actions can call any class that implements Callable, including classes that also implement the earlier managed-package interfaces. The callable implementation receives input, output, and options maps that custom logic can process.","Configure Apex class permission checks so that users require explicit access to the class administering a Remote Action. The ApexClassCheck Omni Interaction Configuration supports this check, and users must also have access to the object and record invoked by the action. Grant the required access through profiles, permission sets, or permission set groups."],connections:[]},
    {id:"ip-flow-control",name:"Flow Control Blocks",icon:"\u{1F500}",desc:"Flow Control Blocks organize Integration Procedure actions and determine how groups of actions execute. Integration Procedure-specific blocks support caching, mutually exclusive conditions, list iteration, and error handling. They allow a server-side process to coordinate complex data operations without presenting a user interface.",tags:["OmniProcessElement"],docs:["Use an If-Else Conditional Block to define mutually exclusive execution paths. Conditions can use formula expressions and values available to the Integration Procedure, allowing different action groups to run for different data or business circumstances. This is useful when transformations or calculations must occur only under selected conditions.","Use a Loop Block to run its contained actions once for each item in a list. Integration Procedures also support complex list processing, and a List Action can merge two lists by matching key values. Keep list-processing logic focused so that each iteration produces data needed by later steps or the final response.","Use a Try-Catch Block to handle failures raised by contained actions while allowing the Integration Procedure to continue with its configured error-handling path. Use a Cache Block to cache the output of contained actions and reduce repeated processing. Caching can apply to part or all of an Integration Procedure when the same data is requested repeatedly."],connections:[]},
    {id:"ip-decision-actions",name:"Decision & Intelligence Actions",icon:"\u{1F9E0}",desc:"Decision & Intelligence Actions incorporate rules-based evaluation into an Integration Procedure. OmniStudio can be combined with Business Rules Engine capabilities to enforce complex logic within a process, including Decision Matrices and Expression Sets. Formula expressions and flow-control conditions determine how evaluated results affect later actions.",tags:["OmniProcess"],docs:["Use decision actions when business rules must be evaluated as part of a server-side orchestration flow. An Integration Procedure can invoke Decision Matrices and Expression Sets, then pass their results to later data operations, branches, or response processing. Centralizing the evaluation in an Integration Procedure makes the same backend logic reusable by different callers.","Combine decision results with conditional blocks to select mutually exclusive paths. Formula expressions can reference process data to determine whether a group of actions runs or whether additional filtering and calculations are required. Configure the procedure's inputs and outputs so that the rule evaluation receives the required context and returns only the data needed downstream."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.business_rules_engine.htm&type=5",connections:[{"planet":"formulas","desc":"Decision actions use expression evaluation for complex rule logic"}]},
    {id:"ip-utility-actions",name:"Utility Actions",icon:"\u{1F6E0}",desc:"Utility Actions perform supporting server-side tasks within an Integration Procedure. Documented actions include returning responses, sending email, creating Chatter posts, running scheduled jobs, merging lists, and declaring expected unit-test results. These actions complement data access, callouts, and flow-control elements in a reusable process.",tags:["OmniProcess"],docs:["Use a Response Action to return data to the entity that called the Integration Procedure. The response can expose the data selected for the caller after preceding actions, transformations, and conditions finish. Integration Procedures can be invoked from Omniscripts, Flexcards, Apex, REST, Flow, and scheduled jobs.","Use a List Action to merge two lists based on matching key values, a Chatter Action to create a Chatter post, or a Batch Action to run a scheduled job. Integration Procedures can also send emails and DocuSign envelopes. Select utility actions according to the side effects and data-processing requirements of the server-side flow.","Use Assert Actions to declare expected results in Integration Procedure unit tests. OmniStudio supports test procedures for testing the entities called by an Integration Procedure. Include assertions that verify the expected output of the configured operations and branches."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_response_action_for_integration_procedures.htm&type=5",connections:[]},
    {id:"ip-compilation",name:"IP Activation & Caching",icon:"\u{1F680}",desc:"IP Activation & Caching prepares an Integration Procedure version for runtime use and improves repeated execution paths. Activation makes the selected version available to callers, while caching can cover selected actions or the procedure more broadly. Runtime security, interaction configuration, and field-level security continue to apply to activated procedures.",tags:["OmniProcessCompilation","OmniProcess"],docs:["Create and validate a new component version before replacing an active Integration Procedure, particularly when changing designers or testing in another org. The standard designer supports activation after edits are saved and validated. Activated Integration Procedures can then provide backend logic to Omniscripts or act as data sources for Flexcards.","Use Cache Blocks to cache the output of selected actions for performance. Integration Procedures also support caching of part or all of the process, reducing repeated processing and database work for frequently requested information. Place caching around stable operations whose results can be reused for the applicable cache scope.","Standard runtime requires appropriate access to Omni Process Compilation and related runtime data. Review field-level security before moving from managed package runtime because standard runtime enforces it more strictly. Integration Procedures also respect security checks and Omni Interaction Configuration settings, including configured Apex class access checks."],connections:[{"planet":"deployment","desc":"Compiled Integration Procedures are packaged in DataPacks"}]}
  ],
  dataFlow: ["Define the Integration Procedure inputs, outputs, actions, and security settings in IP Designer.","Invoke Data Mapper operations, HTTP endpoints, Apex methods, and rules-based evaluations as required.","Apply formula expressions, conditional paths, loops, caching, and error handling to control execution.","Test the procedure, validate its responses, and activate the intended version.","Call the Integration Procedure as Omniscript backend logic or use it as a Flexcard data source.","Export the Integration Procedure through DataPacks for deployment between environments."],
  connections: [{"planet":"omniscripts","desc":"Integration Procedures provide backend logic for OmniScripts"},{"planet":"flexcards","desc":"Integration Procedures serve as data sources for FlexCards"},{"planet":"datamappers","desc":"Integration Procedures invoke Data Mapper operations"},{"planet":"formulas","desc":"Integration Procedures use formula expressions in decision logic"},{"planet":"config","desc":"Integration Procedures respect interaction configuration"},{"planet":"deployment","desc":"Integration Procedures are exported via DataPacks"}]
},

datamappers: {
  packages: ["omnistudio"],
  name: "Data Mappers",
  icon: "\u{1F504}",
  color: "#fb923c",
  description: "Data Mappers are OmniStudio's declarative, server-side components for reading or writing Salesforce object data and performing single-step data-structure transformations. Extract, Load, Transform, and Turbo Extract types address related-object reads, record writes, in-memory restructuring, and direct performance-oriented reads, while mapping formulas handle supported filtering, calculations, and value reformatting. Data Mappers provide data access for Omniscripts, supply Flexcard data sources, and run as actions within Integration Procedures. They can be moved between orgs through DataPacks where supported or through Salesforce CLI on the standard runtime.",
  components: [
    {id:"dm-extract",name:"Extract (Read)",icon:"\u{1F4E5}",desc:"Extract (Read) retrieves mapped data from one or more related Salesforce objects and returns a structured response. It is suited to single-step reads when the source objects have defined relationships and required filtering, calculations, or reformatting can be handled through mappings and formulas. Omniscripts, Flexcards, and Integration Procedures can consume the resulting data.",tags:["OmniDataTransformation","OmniDataTransformationItem"],docs:["A Data Mapper Extract reads Salesforce object data without requiring a custom data-access implementation. It can retrieve fields from related objects and map source values to output nodes. A single Data Mapper is appropriate when the objects have defined relationships and the operation only reads, rather than both reading and writing, Salesforce data.","Configure filters so that values supplied by the calling component match the filter values expected by the Data Mapper. For an Omniscript, output field names can be configured to match the names of elements that the response should populate. During configuration, Omniscript Data JSON can be copied from Preview into the expected output area to help populate output mappings.","Activate and test the Data Mapper independently before using it from another component. Omniscripts can invoke it with a Data Mapper Extract Action, Flexcards can use it as a data source, and Integration Procedures can call it as an action. The response can also be mapped or transformed before it is returned to the caller."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_standard_data_mapper_workflow.htm&type=5",connections:[{"planet":"omniscripts","desc":"OmniScripts invoke Extract Data Mappers to populate form data"},{"planet":"integration","desc":"Integration Procedures use Extract actions for data retrieval"}]},
    {id:"dm-load",name:"Load (Write)",icon:"\u{1F4E4}",desc:"Load (Write) creates or updates Salesforce records from mapped input data. It maps incoming JSON, XML, custom data, or sObject values to Salesforce object fields for a single-step write operation. Omniscripts and Integration Procedures can invoke it to persist new or changed data.",tags:["OmniDataTransformation","OmniDataTransformationItem"],docs:["A Data Mapper Load writes data to Salesforce objects. Use a single Data Mapper when the operation writes, but does not also read, Salesforce data and the affected objects have defined relationships. If a process must both read and write records, an Integration Procedure can orchestrate separate Data Mappers.","Configure input-to-output mappings so that incoming nodes correspond to the Salesforce object fields that must be created or updated. The calling Omniscript can collect or modify user data and then pass that data to the Data Mapper for persistence. Mapping formulas can perform supported calculations or reformat values as part of the operation.","Test the Data Mapper with representative input data before invoking it from a guided process or server-side orchestration. Access depends on the permissions and security configuration applied to Data Mappers and the referenced Salesforce data. When Data Mapper field-level security enforcement is enabled, object and field access is enforced for Data Mapper operations."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_dataraptor_calls_from_apex_47779.htm&type=5",connections:[{"planet":"omniscripts","desc":"OmniScripts invoke Load Data Mappers to save collected data"},{"planet":"integration","desc":"Integration Procedures use Post actions to write data via Data Mappers"}]},
    {id:"dm-transform",name:"Transform (JSON-to-JSON)",icon:"\u{1F503}",desc:"Transform (JSON-to-JSON) changes an in-memory data structure without directly reading from or writing to Salesforce objects. It can restructure, rename, convert, or calculate values by mapping input nodes to output nodes. Omniscripts and Integration Procedures use it when a single declarative transformation can produce the required structure.",tags:["OmniDataTransformation","OmniDataTransformationItem"],docs:["A Data Mapper Transform works with JSON, XML, or other supported in-memory input rather than performing a Salesforce database operation. It maps input nodes to output nodes and can change the shape or names of the resulting data. This makes it suitable for single-step conversion and restructuring tasks.","Use a Data Mapper Transform when the required changes can be expressed through straightforward node mappings and formulas. An Omniscript can use it for more complex transformations than simple real-time formula operations, including converting, restructuring, or renaming data. If transformation requires multiple stages, conditional processing, list operations, or several data-source types, use an Integration Procedure to coordinate the work.","Define the expected input and output structures, configure mappings between their nodes, and preview the result with representative data. The transformed response can then be returned to the calling Omniscript or used by later actions in an Integration Procedure. Because the operation is in memory, it does not itself create, query, or update Salesforce records."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_dataraptor_transform_examples_46793.htm&type=5",connections:[{"planet":"integration","desc":"Integration Procedures use Transform actions between processing steps"}]},
    {id:"dm-turbo",name:"Turbo Extract",icon:"\u{26A1}",desc:"Turbo Extract is a performance-oriented Data Mapper for reading fields from one Salesforce object and related parent objects. It omits formulas and complex output mappings in favor of a more direct extraction model. Omniscripts can invoke it through a Data Mapper Turbo Action, and its output can also supply other OmniStudio consumers.",tags:["OmniDataTransformation","OmniDataTransformationItem"],docs:["A Data Mapper Turbo Extract retrieves fields from a primary Salesforce object and related parent objects. Use it when direct, high-performance extraction is more appropriate than the formulas and configurable output mappings available with a standard Extract. The operation reads data and does not write Salesforce records.","When invoking Turbo Extract from an Omniscript, make the action inputs match the Data Mapper filter values. The action's Response JSON Path must match the Data Mapper's Extract Output Path. Primary-object output field names map directly to Omniscript element names and cannot be renamed.","Related-object fields require additional care when populating an Omniscript. Their values can be referenced through an element's Default Value using the returned Data JSON path. Keep output JSON nodes and Omniscript element names from colliding when doing so, because matching nodes can overwrite related-object values."],connections:[{"planet":"integration","desc":"Integration Procedures use Turbo Extract for high-volume data reads"}]},
    {id:"dm-formulas",name:"Mapping Formulas",icon:"\u{1F9EE}",desc:"Mapping Formulas apply supported formula expressions while a Data Mapper filters, calculates, converts, or reformats values. One formula or a series of formulas can support a single-step read, write, or transformation when the processing remains straightforward. Processes that require conditional multistep behavior or more complex orchestration are better handled by an Integration Procedure.",tags:["OmniDataTransformationItem"],docs:["Data Mapper mappings can use OmniStudio formula expressions to perform supported operations on data values. Formulas can provide filtering, calculations, and reformatting within a declarative mapping. This allows a single Data Mapper to handle processing that does not require separate orchestration steps.","Choose formulas when the required result can be produced by one expression or a sequence of expressions within the Data Mapper. If different conditions determine whether filtering or calculations run, or if node mappings require a series of processing steps, use an Integration Procedure instead. Validate formulas with representative inputs when previewing and testing the Data Mapper."],docUrl:"https://help.salesforce.com/s/articleView?id=sf.os_function_reference_56716.htm&type=5",connections:[{"planet":"formulas","desc":"Mapping formulas use the same function library as OmniStudio formulas"}]}
  ],
  dataFlow: ["Define the Data Mapper type, source objects or input structure, filters, mappings, and formula expressions.","Preview and test the Data Mapper with representative input and verify its output structure.","Activate the Data Mapper before activating Flexcards or other components that reference it.","Invoke the Data Mapper from an Omniscript or an Integration Procedure, or configure it as a Flexcard data source.","Return extracted or transformed data to the caller, or persist mapped values through a Load operation.","Export Data Mappers through DataPacks where supported, or use Salesforce CLI for standard-runtime deployment."],
  connections: [{"planet":"omniscripts","desc":"Data Mappers provide data read/write for OmniScripts"},{"planet":"flexcards","desc":"Data Mappers supply query data for FlexCard data sources"},{"planet":"integration","desc":"Data Mappers are invoked as actions within Integration Procedures"},{"planet":"formulas","desc":"Data Mapper mappings use formula expressions"},{"planet":"deployment","desc":"Data Mappers are exported via DataPacks"}]
},

formulas: {
  packages: ["omnistudio"],
  name: "Functions & Formulas",
  icon: "\u{1D453}",
  color: "#facc15",
  description: "Functions & Formulas provides expression capabilities for calculations, transformations, comparisons, and conditional evaluation across OmniStudio. Its documented functions operate on mathematical values, strings, dates and times, lists, arrays, and JSON structures, with syntax and input constraints enforced during evaluation. Formulas power calculations in Omniscript elements, compute derived values in Data Mapper mappings, and drive conditional logic in Integration Procedures. Conversion and formatting functions help prepare values for subsequent formula operations.",
  components: [
    {id:"fn-math-logic",name:"Math & Logical Functions",icon:"\u{2795}",desc:"Math & Logical Functions provide calculations, comparisons, and conditional evaluation within OmniStudio formulas. They include conditional functions such as IF, mathematical functions such as SQRT, and operators for arithmetic and comparison. These expressions support calculated values in Omniscript elements, derived values in Data Mapper mappings, and conditional logic in Integration Procedures.",tags:["OmniProcessElement"],docs:["Conditional expressions use functions such as IF to choose between results based on an evaluated condition. An IF condition cannot evaluate an array that contains an empty string, including an array populated from an empty field. Formula authors must therefore ensure that the condition receives an acceptable value before evaluation.","Mathematical expressions reject invalid operations. SQRT cannot calculate the square root of a negative number, and division by zero produces an error. The comparison operator ~= accepts strings rather than numeric values, and operators must use the supported syntax."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omniscript_functions.htm&type=5",connections:[{"planet":"omniscripts","desc":"Math and logical functions power OmniScript calculations"},{"planet":"integration","desc":"Logical functions drive conditional branching in Integration Procedures"}]},
    {id:"fn-string",name:"String Functions",icon:"\u{1F524}",desc:"String Functions operate on text values in OmniStudio formulas. Supported functions include encoding, concatenation, joining, splitting, indexing, substring extraction, maximum-string selection, and conversion to a string. String-function comparisons are case-sensitive, unlike most general function and operator comparisons.",tags:["OmniProcessElement"],docs:["The documented string functions include BASE64ENCODE(data), CONCAT(string...), JOIN(string..., token), MAXSTRING(string...), SPLIT(string, token), STRINGINDEXOF(string, substring), SUBSTRING(string, startIndex, endIndex), and TOSTRING(data). JOIN combines string values using a specified token, while SPLIT separates a string at that token. Both functions require a correctly formed token parameter.","Some string functions reject null or empty input. Documented error cases include BASE64ENCODE(null), CONCAT(\"\"), TOSTRING(null), and TOSTRING(\"\"). Formula authors should validate input values and supply all required parameters before invoking these functions."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omnistudio_formulas_and_functions.htm&type=5",connections:[]},
    {id:"fn-date-time",name:"Date & Time Functions",icon:"\u{1F4C5}",desc:"Date & Time Functions extract date or time portions, calculate differences, and provide current-date values in OmniStudio formulas. Documented functions include DAY, HOUR, MINUTE, SECOND, TIMEDIFF, TODAY, YEAR, and AGE. Inputs must use formats accepted by the individual function.",tags:["OmniProcessElement"],docs:["Date and time extraction functions return a selected part of an input value. For example, YEAR applied to a CreatedDate value can return its four-digit year. DAY, HOUR, MINUTE, and SECOND provide corresponding date or time portions, while TIMEDIFF compares two time values.","Date and time inputs must follow supported formatting rules. AGE does not accept the example format \"01 Jan 2025\", and HOUR does not accept a time whose time zone is separated from the time by a space, such as \"21:00:56 +0900\". TODAY() no longer accepts a format parameter."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omnistudio_formulas_and_functions.htm&type=5",connections:[]},
    {id:"fn-list-json",name:"List & JSON Functions",icon:"\u{1F4CB}",desc:"List & JSON Functions work with grouped values, arrays, and JSON structures in OmniStudio formulas. Lists can contain values of any supported data type, including nested lists, while arrays can be named or anonymous and can contain nested arrays or JSON objects. MAPTOLIST(jsonObject) converts a JSON object for list-oriented processing.",tags:["OmniProcessElement","OmniDataTransformationItem"],docs:["A list is a comma-separated series of values that is often enclosed in parentheses. Its values can have different data types and can include nested lists, and the list itself is anonymous. Examples include integer lists such as (1, 2, 3) and string lists such as (\"a\", \"b\", \"c\").","An array is a comma-separated series enclosed in square brackets. Arrays can be named or anonymous and can contain values, nested arrays, or JSON objects; an anonymous array is also called a JSON list. MAPTOLIST(jsonObject) is the documented list and array function for mapping a JSON object to a list."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_list_input_for_dataraptors_47431.htm&type=5",connections:[{"planet":"datamappers","desc":"JSON functions process list data in Data Mapper transformations"}]},
    {id:"fn-datatypes",name:"Data Types & Conversion",icon:"\u{1F522}",desc:"Data Types & Conversion defines how values are represented and supplied to OmniStudio formulas. The documented value forms include strings, lists, and arrays, with TOSTRING(data) available for string conversion. Correct quoting, delimiters, and input values are required for successful evaluation.",tags:["OmniProcessElement"],docs:["Strings are sequences of characters that can represent words, numbers, or dates. They must be enclosed in matching single or double quotation marks, and matching quote types can be nested within the other type. Strings are sorted lexicographically by comparing their individual characters.","Lists use comma-separated values and are often enclosed in parentheses, whereas arrays use square brackets and can be named or anonymous. Both can contain values of different data types and can include nested structures. TOSTRING(data) converts data to a string, but the documented error cases show that it does not accept null or an empty string."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omnistudio_formulas_and_functions.htm&type=5",connections:[]}
  ],
  dataFlow: ["Supply formula inputs from the current OmniStudio component or its data.","Apply conversions and string, date, mathematical, list, or JSON functions as needed.","Compute derived values in Data Mapper mappings.","Evaluate conditional logic in Integration Procedures.","Use calculated results in Omniscript elements."],
  connections: [{"planet":"omniscripts","desc":"Formulas power calculations in OmniScript elements"},{"planet":"integration","desc":"Formulas drive conditional logic in Integration Procedures"},{"planet":"datamappers","desc":"Formulas compute derived values in Data Mapper mappings"}]
},

lwc: {
  packages: ["omnistudio"],
  name: "Custom LWC Extensions",
  icon: "\u{1F4BB}",
  color: "#60a5fa",
  description: "Custom LWC Extensions provide the developer extension point for adding specialized Lightning Web Component behavior to OmniStudio user experiences. Custom components extend the Omniscript element palette and Flexcard rendering when declarative configuration doesn’t satisfy a requirement. They can participate in runtime data context and event-driven interaction while remaining part of the surrounding guided process or contextual card. OmniStudio Lightning Web Components can be set up, extended, and deployed with Salesforce development and deployment tools.",
  components: [
    {id:"lwc-custom-elements",name:"Custom OmniScript Elements",icon:"\u{1F9E9}",desc:"Custom OmniScript Elements extend the OmniStudio Omniscript element palette when declarative elements don’t meet a guided-process requirement. Developers use Lightning Web Components to add specialized behavior while preserving the surrounding Omniscript composition. Because generated Omniscripts are Lightning Web Components, they can also be modified according to business logic.",tags:["OmniProcessElement"],docs:["OmniStudio uses a Lightning Web Component runtime, and an activated or generated Omniscript can run as a Lightning Web Component. Custom elements provide a developer extension point beyond the elements available in the declarative Omniscript designer. They participate in guided interactions that display information, collect input, and respond to user choices.","Set up and extend the Lightning Web Component using the OmniStudio LWC guidance, then incorporate it into the relevant Omniscript composition. The component can use the Omniscript data context to work with the guided process’s JSON data model and associated events. Preview and test the completed Omniscript before activation and deployment."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_create_a_custom_lightning_web_component_for_omniscript_17512.htm&type=5",connections:[{"planet":"omniscripts","desc":"Custom elements appear in the OmniScript designer palette"}]},
    {id:"lwc-custom-cards",name:"Custom FlexCard Components",icon:"\u{1F5BC}",desc:"Custom FlexCard Components extend Flexcard rendering beyond the elements available in the declarative designer. They support specialized contextual interfaces while participating in a Flexcard that displays data and launches actions. Generated Flexcards are Lightning Web Components and can be modified when required by business logic.",tags:["OmniUiCard"],docs:["A Flexcard is a contextual block that combines pertinent information with links or actions, and the generated Flexcard is a Lightning Web Component. Custom Lightning Web Components extend how a Flexcard renders content when its standard elements aren’t sufficient. The resulting component remains part of a Flexcard experience deployed to Lightning or Experience Cloud pages.","Configure the custom component in relation to the Flexcard’s data, layout, and actions. Flexcards can retrieve data from multiple source options, apply conditional display logic, launch Omniscripts, display flyouts, and fire events. Preview and debug the Flexcard before activation and publication."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_activateconfigureand_publish_flexcards_24744.htm&type=5",connections:[{"planet":"flexcards","desc":"Custom components extend FlexCard rendering capabilities"}]},
    {id:"lwc-data-binding",name:"Data Context & Events",icon:"\u{1F517}",desc:"Data Context & Events connects custom Lightning Web Components with the runtime context of an Omniscript or Flexcard. In an Omniscript, a custom component can read from and write to the hierarchical JSON data model and participate in process events. In a Flexcard, contextual data and event-driven actions support interaction between the custom rendering and the surrounding card.",tags:["OmniProcess","OmniProcessElement"],docs:["An Omniscript carries values and responses through its runtime data structure as users progress through the guided interaction. A custom Lightning Web Component can use the Omniscript data context and documented interfaces to work with that data rather than maintaining a separate process model. Event integration allows the component to participate in Omniscript behavior such as navigation and validation.","Flexcards render information and actions relevant to the current customer context. Their actions can update an Omniscript, display a flyout, navigate to another destination, update field values, or fire an event. A custom Lightning Web Component should use the available Flexcard context and event configuration so that its behavior remains coordinated with the containing card."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_create_and_map_data_inside_the_custom_lwc_element_18140.htm&type=5",connections:[{"planet":"omniscripts","desc":"Data context API connects custom elements to OmniScript data model"}]}
  ],
  dataFlow: ["Identify an Omniscript element or Flexcard rendering requirement not covered declaratively.","Set up and implement the custom Lightning Web Component.","Connect the component to the Omniscript data context or Flexcard context and events.","Add the component to the applicable Omniscript or Flexcard composition.","Preview and test the complete user experience.","Deploy the Lightning Web Component and related OmniStudio content."],
  connections: [{"planet":"omniscripts","desc":"Custom LWCs extend the OmniScript element palette"},{"planet":"flexcards","desc":"Custom LWCs extend FlexCard rendering"}]
},

config: {
  packages: ["omnistudio"],
  name: "Configuration & Settings",
  icon: "\u{2699}",
  color: "#64748b",
  description: "Configuration & Settings provides centralized administration for the operational behavior of OmniStudio across an org. OmniInteractionConfig records govern Omniscript runtime behavior, Integration Procedure execution, security checks, integrations, and Experience Cloud-specific behavior, while Global Auto Number definitions provide configurable sequential identifiers. Usage-based entitlements support analytics reporting, and electronic-signature settings connect guided processes to DocuSign. Because these settings operate across components and environments, they also affect the context in which OmniStudio solutions are tested and validated.",
  components: [
    {id:"cfg-interaction",name:"Interaction Configuration",icon:"\u{1F4CB}",desc:"Interaction Configuration centralizes key-value settings that alter OmniStudio behavior across an org. Administrators use OmniInteractionConfig records to enable security checks, select runtime features, configure integrations, and adjust component behavior. These settings can affect Omniscripts, Flexcards, Data Mappers, Integration Procedures, Experience Cloud deployments, and testing contexts.",tags:["OmniInteractionConfig"],docs:["Create Omni Interaction Configuration records in Setup by specifying a label, name, and value for each supported setting. Documented settings enable behaviors such as locale-based date and time processing, Lightning Rich Text Editor use, preservation of the selected designer during upgrades, and omission of the userProfile node from Omniscript previews. Because each setting has a defined name and expected value, enter the documented values without changing their spelling or case when instructed.","Security-related configurations govern access checks across OmniStudio. ApexClassCheck requires explicit Apex class access for remote actions, EnforceDMFLSAndDataEncryption enforces object and field-level security for Data Mappers and controls access to encrypted values, and EnableQueryWithFLS applies field-level security to Flexcard SOQL and SOSL queries. CheckCachedMetadataRecordSecurity is required when caching is used with sharing-based security for Data Mappers and Integration Procedures.","Interaction configurations also support deployment and integration scenarios. RetainDesignerSettingOnUpgrade preserves the selected designer when an org package is upgraded, while DocuSignAccountId and DocuSignNamedCredential provide DocuSign authorization details. Administrators should validate changed settings in a cloned org or a new component version because configuration choices can affect runtime behavior, Experience Cloud use, and test results."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_enable_standard_omnistudio_runtime.htm&type=5",connections:[{"planet":"omniscripts","desc":"Interaction config controls OmniScript runtime behavior"},{"planet":"integration","desc":"Interaction config governs IP caching and execution policies"},{"planet":"experience","desc":"Interaction config defines settings for Experience Cloud contexts"}]},
    {id:"cfg-autonumber",name:"Global Auto Number",icon:"\u{1F522}",desc:"Global Auto Number provides configurable sequential identifiers for OmniStudio business processes. An Omni Global Auto Number definition can control increments, padding, prefixes, and separators. The feature is configured at the org level and can require migration preparation when incompatible custom records or rollback configurations are present.",tags:["OmniProcess"],docs:["Use Omni Global Auto Number when a process requires custom sequential numbering. Configure the number definition with the required increment, padding, prefix, and separator options, and then use the resulting identifier in the applicable business process. This centralizes number generation instead of requiring each process to implement its own numbering logic.","Before enabling Omni Global Auto Number, verify that the org is ready to use standard objects and records. Enablement can fail when custom records remain or when the RollbackDRChanges or RollbackIPChanges Omni Interaction Configurations are enabled. In that situation, disable both configurations and migrate the applicable data with the OmniStudio Migration Assistant before trying again."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_setting_enable_ogan.htm&type=5",connections:[{"planet":"omniscripts","desc":"Auto numbers generate sequential IDs within guided processes"}]},
    {id:"cfg-entitlements",name:"Usage-Based Entitlements",icon:"\u{1F4CA}",desc:"Usage-Based Entitlements provide visibility into an org’s licensed OmniStudio usage. They associate component execution with the usage available to the org. Entitlement information feeds analytics reporting so administrators can review consumption in relation to licensed access.",tags:["OmniInteractionConfig"],docs:["Review the org’s OmniStudio usage-based entitlements to understand licensed usage and component execution. OmniStudio availability depends on the appropriate org permissions and licenses being enabled. Use the resulting entitlement information in analytics reporting to monitor usage across the org."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_usage_entitlements.htm&type=5",connections:[{"planet":"analytics","desc":"Entitlement data feeds into analytics dashboards"}]},
    {id:"cfg-esignature",name:"Electronic Signatures",icon:"\u{270D}",desc:"Electronic Signatures connect Omniscripts and Integration Procedures with DocuSign templates and envelopes. The integration uses a DocuSign application, Salesforce authentication configuration, named credentials, and Omni Interaction Configuration records. It supports default authorization and optional sending or signing on behalf of another configured user.",tags:["OmniElectronicSignatureTemplate"],docs:["Prepare the integration by creating a DocuSign developer account and an application that uses Authorization Code Grant. Record the DocuSign Account ID, Base URI, Integration Key, and Secret Key, and then configure the corresponding authentication provider and OAuth 2.0 named credential in Salesforce. Authenticate the named credential with the appropriate DocuSign account before using it from OmniStudio.","Add DocuSignAccountId and DocuSignNamedCredential records in Omni Interaction Configuration to provide the DocuSign account and named credential information. For an Experience Cloud site, add the DocuSign login page as an active trusted URL and permit frame-src content because DocuSign runs in an iframe. These settings allow the DocuSign content and authorization flow to operate in the site context.","Prepare DocuSign templates to receive data from Omniscripts or Integration Procedures, retrieve the templates in OmniStudio, and map process data to a template with a Data Mapper Transform. To send or sign on behalf of another user, add the documented DocuSign named credential field to the User object and assign the appropriate named credential to each user. If no send-on-behalf configuration exists, Salesforce uses the default administrator user."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_integrate_docusign_with_omniscripts_23535.htm&type=5",connections:[{"planet":"omniscripts","desc":"E-signature actions are invoked from OmniScript steps"}]}
  ],
  dataFlow: ["Define OmniInteractionConfig records for required runtime, security, integration, and Experience Cloud behavior.","Configure Omni Global Auto Number definitions for processes that require sequential identifiers.","Connect DocuSign authentication, named credentials, templates, and data mappings to Omniscripts or Integration Procedures.","Validate configuration-dependent Omniscript and Integration Procedure behavior in the intended test context.","Review usage-based entitlements and feed consumption information into analytics reporting."],
  connections: [{"planet":"omniscripts","desc":"Configuration settings control OmniScript runtime behavior"},{"planet":"integration","desc":"Configuration governs Integration Procedure execution"},{"planet":"analytics","desc":"Usage entitlements feed analytics reporting"},{"planet":"testing","desc":"Configuration settings affect test execution context"},{"planet":"experience","desc":"Configuration defines Experience Cloud-specific behavior"}]
},

experience: {
  packages: ["omnistudio"],
  name: "Experience Cloud",
  icon: "\u{1F310}",
  color: "#f87171",
  description: "Experience Cloud extends OmniStudio guided processes and contextual interfaces to customer, partner, and public-facing sites. Active Omniscripts can be embedded in Experience Builder pages, while Flexcards display relevant data and expose actions in the user's context. Permission sets, profiles, sharing rules, field-level security, and Omni Interaction Configuration settings govern access for guest and authenticated users. Custom Lightning Web Components can wrap or extend OmniStudio components when Experience Cloud runtime and composition requirements call for custom integration.",
  components: [
    {id:"ec-components",name:"Experience Builder Components",icon:"\u{1F9E9}",desc:"Experience Builder Components bring OmniStudio guided interactions and contextual interfaces to Experience Cloud sites. After activation, Omniscripts can be added to Aura-based or Lightning Web Runtime (LWR) Experience Builder pages with the standard component. Flexcards can display data and launch actions from Experience Cloud pages. Runtime and site-type considerations determine whether standard components or generated Lightning Web Components are used.",tags:["OmniProcess","OmniUiCard"],docs:["In the standard runtime, add an active Omniscript to an Experience Builder page by dragging the Omniscript component onto the canvas. Aura-based sites list the component under Process Automation, while LWR Experience Builder lists it under Customer Interactions. Select the required type and subtype, theme, display mode, language, and language direction, and then preview the site. An Omniscript can appear directly on the page or open from a button.","Flexcards are declaratively created components that present contextual information and actions, and they can be added to Experience Cloud pages. Their data sources retrieve the information displayed on the card, while actions can launch or update an Omniscript, navigate elsewhere, display a flyout, fire an event, or update field values. Standard Flexcard and Omniscript components are recommended for Aura-based Experience Builder pages after activation. Embedding a Flexcard in an LWR Experience site requires the managed package runtime setting to remain enabled and the generated LWC to be used.","Aura-based and LWR Experience Cloud sites implement their own styling. When an Omniscript has a modified appearance, configure the token overrides appropriate to the consuming site; Aura-based and LWR sites use different design tokens. For LWR sites, style and visibility must be controlled in the Omniscript designer because the corresponding native Experience Builder tabs don't work with Omniscript elements. Republish sites, including affected child Omniscripts, after making Omniscript changes."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omnistudio_on_experience_cloud.htm&type=5",connections:[{"planet":"omniscripts","desc":"OmniScripts are placed on Experience Cloud pages"},{"planet":"flexcards","desc":"FlexCards are rendered on Experience Cloud pages"}]},
    {id:"ec-authentication",name:"Guest & Authenticated Access",icon:"\u{1F512}",desc:"Guest & Authenticated Access controls which Experience Cloud users can read and run public-facing OmniStudio content while preserving object- and field-level security. Guest users require specifically provisioned permissions and sharing rules for active content. Authenticated Experience Cloud users receive access through permission sets, profiles, and applicable record sharing. Omni Interaction Configuration settings enforce additional Apex, Data Mapper, and query security checks.",tags:["OmniProcess"],docs:["Experience Cloud users require access to the OmniStudio content used by public-facing components. For authenticated users, create a permission set that grants Read and View All Fields access to the documented Omni Process, Omni Process Compilation, and Omni Process Element records, and use an appropriate Experience Cloud user profile. Partner Experience Cloud users also require the documented field-level access for Omni Process Compilation, Omni Data Transformation, and Omniscript Saved Sessions in the standard runtime. Sharing rules can provide access to the necessary component records for testing or partner-facing use cases.","For guest access, clone the OmniStudio User permission set and grant the documented read access to Omni Process, Omni Process Compilation, Omni Process Element, and Omni UI Card content. Configure Omniscript Saved Sessions without Create, Edit, or Delete access when following the guest permission-set procedure. Create criteria-based guest sharing rules for active OmniStudio content, and configure the site's guest user profile with the permission that enables consumers and partners to execute Omniscripts, Data Mappers, and Flexcards through an Experience Cloud site or off-platform. Guest access remains subject to the configured object, field, record, and Apex class permissions.","Use Omni Interaction Configuration records to enable security checks that affect portal users. ApexClassCheck requires explicit Apex class access for remote actions called from Omniscripts or Flexcards, helping prevent unauthorized guest access through Apex remote calls. EnforceDMFLSAndDataEncryption enforces object- and field-level security for Data Mappers and protects encrypted field values, while EnableQueryWithFLS enforces field-level security for SOQL and SOSL queries used by Flexcards. When an LWR site is opened as an unauthenticated user, it shows only Flexcards whose data is available to guest users; configure site login when authenticated access is required."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_security_for_dataraptors_and_integration_procedures_48147.htm&type=5",connections:[{"planet":"config","desc":"Authentication settings reference interaction configuration"}]},
    {id:"ec-lwc",name:"Custom LWC Extensions",icon:"\u{1F4BB}",desc:"Custom LWC Extensions adapt or embed generated OmniStudio Lightning Web Components for Experience Cloud use cases. Omniscripts and Flexcards are generated as Lightning Web Components, and their generated implementations can be modified when business logic requires it. Experience Cloud runtime type affects how custom components reference, style, and load their OmniStudio dependencies.",tags:["OmniProcess","OmniUiCard"],docs:["An active Omniscript can be referenced from a custom Lightning Web Component through the standard runtime wrapper. The wrapper identifies the Omniscript by mandatory type, subtype, and language attributes, and it uses the Lightning theme by default unless the Newport theme is specified. For an LWR Experience Cloud site, a wrapper component is required when an Omniscript is referenced from another Lightning Web Component. Generated Flexcards and Omniscripts are also Lightning Web Components that can be modified based on business logic.","LWR Experience Cloud sites support custom Lightning Web Components, but nested Flexcards and Omniscripts require their dependencies to be available to the site's cached runtime. Add the nested components to a hidden site page, or place the dependent Flexcards and Omniscripts on the same page as the custom component and use visibility conditions to keep them hidden from users. This allows the LWR site to discover and load the appropriate nested components at runtime. Changes to embedded Omniscripts require the affected site content to be republished."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omnistudio_lightning_web_components_58153.htm&type=5",connections:[]}
  ],
  dataFlow: ["Activate the Omniscripts and Flexcards intended for the Experience Cloud site.","Configure Omni Interaction Configuration security checks for the portal runtime.","Grant guest or authenticated users the required permissions and record access.","Place Omniscripts and Flexcards on the appropriate Experience Builder pages.","Configure custom LWC wrappers or nested dependencies when the site runtime requires them.","Preview, publish, and test the site under each intended user context."],
  connections: [{"planet":"omniscripts","desc":"OmniScripts are embedded in Experience Cloud pages"},{"planet":"flexcards","desc":"FlexCards are displayed on Experience Cloud pages"},{"planet":"config","desc":"Experience Cloud uses interaction configuration for portal settings"}]
},

agentforce: {
  packages: ["omnistudio"],
  name: "Agentforce Integration",
  icon: "\u{1F916}",
  color: "#c084fc",
  description: "Agentforce Integration connects OmniStudio components with Agentforce agents, subagents, and actions. OmniScripts are exposed as actions for structured guided processes, and Integration Procedures are configured as actions for real-time automation and data access. Flexcards serve as context surfaces that present relevant information for agents. Agent and subagent configuration coordinates these components around specific conversation intents and tasks.",
  components: [
    {id:"af-actions",name:"Agent Actions",icon:"\u{26A1}",desc:"Agent Actions connect Agentforce agents to executable OmniStudio components. OmniScripts can be exposed as actions for guided processes, while Integration Procedures can be prepared as actions for real-time automation and data access. Integration Procedure inputs and outputs are defined and verified as JSON before the action is added to an agent from the Agentforce Studio Asset Library. A configured subagent uses the action to handle a specific intent or task during an interaction.",tags:["OmniProcess"],docs:["An Integration Procedure must be prepared before it can be used as an Agent Action because Agentforce expects a different data format from the standard Integration Procedure format. In the Integration Procedure preview, select Configure Agentforce and define the input and output data in JSON. JSON keys can contain only alphanumeric characters and cannot contain special characters. Verifying the data automatically updates the structure to a format compatible with Agentforce.","After verification, save and activate the Integration Procedure. In Agentforce Studio, open the target agent and subagent, add an action from the Asset Library, and select the Integration Procedure action. Agent Actions serve as connectors between Agentforce and the Integration Procedure. Once added and configured, the Integration Procedure can run during agent-customer interactions.","An agent manages conversation flows and executes its configured Agent Actions. Subagents identify the specific intents or tasks associated with those actions. OmniScripts can likewise be exposed as Agentforce actions, allowing an agent to initiate a structured guided process on behalf of a user. The agent and relevant subagent must be configured before the action is used."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_agentforce_for_omnistudio.htm&type=5",connections:[{"planet":"omniscripts","desc":"OmniScripts are exposed as callable agent actions"},{"planet":"integration","desc":"Integration Procedures execute as agent backend operations"}]},
    {id:"af-context",name:"Context Surfaces",icon:"\u{1F4C4}",desc:"Context Surfaces use Flexcards to provide relevant OmniStudio context for agents. Flexcards can participate in experiences that integrate data supplied by Data Mappers, Integration Procedures, and OmniScripts. Agentforce also provides a Flexcard Information subagent that answers documentation questions about Flexcards and their integration with other OmniStudio components.",tags:["OmniUiCard"],docs:["Flexcards serve as context surfaces for agents, presenting relevant information within agent-assisted interactions. They complement executable OmniScripts and Integration Procedures by supplying a contextual interface rather than performing the server-side action itself. Flexcards can also invoke Integration Procedures, consistent with their role in connected OmniStudio experiences.","The Flexcard Information subagent is available for Flexcard designers who need information about Flexcards and their integration with Data Mappers, Integration Procedures, and OmniScripts. Its included documentation action generates answers and links to relevant Salesforce Help articles. For example, a designer can ask how to launch an OmniScript from a Flexcard."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_agentforce_for_omnistudio.htm&type=5",connections:[{"planet":"flexcards","desc":"FlexCards provide contextual data display for agents"}]},
    {id:"af-orchestration",name:"Agent Orchestration",icon:"\u{1F3AF}",desc:"Agent Orchestration coordinates agents, subagents, Agent Actions, and OmniStudio components around specific conversation intents and tasks. Agents manage conversation flows, while subagents associate focused responsibilities with available actions. Integration Procedures provide reusable real-time automation and data access, OmniScripts provide guided processes, and Flexcards provide contextual surfaces. Together, these configured elements support interactions that require context and process execution.",tags:["OmniProcess"],docs:["In Agentforce Studio, an agent manages the conversation flow and executes Agent Actions. Subagents define the particular intents or tasks that the agent handles and are associated with the relevant actions. An Integration Procedure action is added to a selected subagent from the Asset Library after its data has been prepared and the Integration Procedure has been activated. This organization enables the agent to invoke the configured automation during customer interactions.","OmniStudio components can participate in connected flows beyond the Agentforce action itself. Integration Procedures can be invoked from OmniScripts and Cards, as well as from Apex classes, batch jobs, REST APIs, and Salesforce flows. Within an Agentforce experience, executable OmniScripts and Integration Procedures can be combined with Flexcard context surfaces according to the configured agent and subagent responsibilities.","Specialized Agentforce subagents also assist OmniStudio designers and implementation teams. Documentation-oriented subagents answer questions about Data Mappers, Integration Procedures, Flexcards, and OmniScripts and link to relevant Salesforce Help content. The Product Strategy subagent can produce architecture and build-planning guidance, while the Diagnostics subagent can inspect an OmniScript by ID and report potential errors and warnings."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_agentforce_for_omnistudio.htm&type=5",connections:[{"planet":"omniscripts","desc":"Orchestration chains OmniScript guided processes"},{"planet":"flexcards","desc":"Orchestration uses FlexCards for agent data context"}]}
  ],
  dataFlow: ["Enable OmniStudio metadata support and assign the required OmniStudio permissions.","Select the OmniScript or Integration Procedure to expose as an Agentforce action.","Define and verify Integration Procedure input and output JSON, then save and activate it.","Add the action from the Agentforce Studio Asset Library to the appropriate subagent.","Configure the agent and subagent for the intended conversation task.","Invoke the action during an interaction and present relevant context through Flexcards."],
  connections: [{"planet":"omniscripts","desc":"OmniScripts are exposed as Agentforce actions"},{"planet":"flexcards","desc":"FlexCards serve as context surfaces for agents"}]
},

analytics: {
  packages: ["omnistudio"],
  name: "OmniStudio Analytics",
  icon: "\u{1F4C8}",
  color: "#2dd4bf",
  description: "OmniStudio Analytics tracks and measures user interactions with Omniscripts and Flexcards in the standard runtime. Tracking configuration routes event data to internal OmniAnalytics dashboards, Google Analytics 4, or both without requiring template edits or custom scripts. Collected measurements include clicks, process and step completion, load time, and viewing time, helping administrators identify user interest and points of abandonment. Analytics also provides reporting visibility into entitlement usage and configuration.",
  components: [
    {id:"oa-tracking",name:"Tracking Definitions",icon:"\u{1F4CD}",desc:"Tracking Definitions configure which OmniStudio Omniscript and Flexcard interactions are tracked and how their event data is handled. Tracking groups associate components with underlying tracking metadata, while component settings enable analytics at runtime. Tracked data can be sent to internal OmniAnalytics storage, Google Analytics 4, or both.",tags:["OmniAnalyticsTrackingDef"],docs:["OmniAnalytics tracks user interactions with Omniscripts and Flexcards through tracking components. Administrators first enable OmniStudio Analytics and choose whether to store tracking data internally, publish event notifications, or use both options. Tracking configuration controls the data sent, its structure, and its destination without requiring template edits or scripts.","Internal tracking requires an Internal Tracking Group and tracked components placed on an activated Lightning app page. The Omniscript or Flexcard standard component must reference an active component and have Enable OmniStudio Analytics selected. Omniscripts used with Google Analytics must also have tracking enabled and include the required Google Analytics and Google Tag Manager message data.","When a Flexcard in a tracking group is modified, the tracking group isn't updated automatically. Remove the Flexcard from the group and add it again for the changes to work as expected. After changing a tracking group, refresh the browser."],docUrl:"https://developer.salesforce.com/docs/atlas.en-us.platform_events.meta/platform_events/sforce_api_objects_omnitrackingevent.htm",connections:[{"planet":"omniscripts","desc":"Tracking definitions capture events from OmniScript execution"}]},
    {id:"oa-metrics",name:"Engagement Metrics",icon:"\u{1F4CA}",desc:"Engagement Metrics measure how users view, navigate, and interact with tracked OmniStudio experiences. The collected data includes completion percentages, impressions and clicks, load times, and viewing times for Omniscripts, Flexcards, and Omniscript steps. These measurements help identify user interest, abandonment within a flow, and steps that are slow to load or difficult to understand.",tags:["OmniAnalyticsTrackingDef"],docs:["OmniAnalytics collects interaction data such as clicks per product, offer, or promotion impression and clicks per UI action impression. It also measures the percentage of Omniscripts completed and the percentage of Omniscript steps completed. These metrics show which content attracts interaction and where users stop progressing through a guided process.","Performance and engagement measurements include load time and viewing time for Flexcards, Omniscripts, and Omniscript steps. For internal reporting to populate correctly, Omniscript steps require Step Label values, and the relevant messaging framework options must be enabled. The Omniscript or Flexcard must also be active and referenced by an activated page component with OmniStudio Analytics enabled."],connections:[]},
    {id:"oa-dashboards",name:"Analytics Dashboards",icon:"\u{1F4C9}",desc:"Analytics Dashboards present tracked OmniStudio interaction data for review and reporting. Internal OmniAnalytics dashboards can show reports for individual Omniscripts and Flexcards, while the same event data can also be sent to Google Analytics 4. This visibility supports analysis of engagement, process completion, entitlement usage, and analytics configuration.",tags:["OmniAnalyticsTrackingDef"],docs:["User interaction data flows from Omniscripts and Flexcards through tracking components into internal OmniAnalytics dashboards. Administrators can open the relevant component tab and run a report for an Omniscript or Flexcard. Internal dashboards require an Internal Tracking Group and tracked components configured on an activated Lightning app page.","OmniAnalytics can send the same tracked data to internal dashboards, a third-party analytics system, or both. Third-party analytics uses integration with Google Analytics 4 and Google Tag Manager, while internal storage is controlled through OmniAnalytics settings. If internal report data doesn't appear after 30 minutes, verify step labels, messaging framework settings, component activation, standard-runtime compatibility, and the page component's analytics setting."],connections:[{"planet":"config","desc":"Dashboards display entitlement usage and configuration metrics"}]}
  ],
  dataFlow: ["Enable OmniStudio Analytics and select the internal and external tracking destinations.","Create an Internal Tracking Group and associate the required Omniscripts and Flexcards.","Activate the components and enable OmniStudio Analytics on their page components.","Capture user interactions, completion measurements, load times, and viewing times.","Send tracked events to internal dashboards, Google Analytics 4, or both.","Review engagement, entitlement usage, and configuration reporting."],
  connections: [{"planet":"omniscripts","desc":"Analytics track OmniScript user interactions"},{"planet":"config","desc":"Analytics report on entitlement usage and configuration"}]
},

testing: {
  packages: ["omnistudio"],
  name: "Testing & Quality",
  icon: "\u{2705}",
  color: "#a3e635",
  description: "Testing & Quality covers OmniStudio tools for validating Omniscript and Flexcard configurations during design and before deployment. OmniStudio Design Assistant reports component health, complexity, performance concerns, recommended limits, and best-practice deviations in real time. Preview and debugging capabilities let designers exercise component behavior and inspect runtime data, while UTAM supports automated end-to-end browser testing through Page Object Models. Validation occurs within the applicable OmniStudio interaction configuration context so observed behavior reflects runtime conditions.",
  components: [
    {id:"tq-utam",name:"UTAM Test Framework",icon:"\u{1F9EA}",desc:"The UTAM Test Framework supports automated end-to-end UI testing for OmniStudio Omniscripts and Flexcards. It uses resilient Page Object Model abstractions to represent component interfaces in browser tests. Separate guidance covers the UTAM testing workflow and writing tests for each supported component type.",tags:["OmniProcess","OmniUiCard"],docs:["UTAM provides a structured approach to automating OmniStudio user-interface tests. Test authors interact with Page Object Models instead of directly coupling every test step to the rendered interface. This abstraction supports end-to-end browser testing of Omniscripts and Flexcards.","Use the UTAM testing workflow to create and run tests that exercise the expected user experience. Flexcard tests can validate contextual interfaces and user actions, while Omniscript tests can validate guided, step-by-step interactions. Run tests in the applicable OmniStudio interaction configuration context so test behavior reflects the component’s runtime conditions."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_utam_flexcards_omniscripts.htm&type=5",connections:[{"planet":"omniscripts","desc":"UTAM page objects automate testing of OmniScript flows"},{"planet":"flexcards","desc":"UTAM page objects test FlexCard rendering and interactions"}]},
    {id:"tq-design-assistant",name:"Design Assistant",icon:"\u{1F4A1}",desc:"OmniStudio Design Assistant provides real-time feedback about the health and design quality of Omniscripts and Flexcards while they are being authored. It evaluates factors such as component complexity, performance, recommended limits, and alignment with best practices. Visual indicators and detailed reports identify informational and warning conditions so designers can address potential issues before runtime.",tags:["OmniProcess","OmniUiCard"],docs:["OmniStudio Design Assistant monitors Omniscript and Flexcard designs and provides actionable alerts within their designers. It assesses complexity by considering elements, data sources, actions, and other design factors. The resulting feedback helps identify design inefficiencies that can contribute to latency, low throughput, resource overuse, or potential runtime failures.","Informational and warning icons in the designer show when a configuration approaches or exceeds a recommended threshold. Selecting an icon displays the number of messages and provides access to a detailed report in the Design Assistant panel. Designers can review the Information and Warning tabs, expand individual messages, and use the reported current and recommended counts to refine the component.","Design Assistant promotes consistent design standards by checking configurations against OmniStudio best practices. Its real-time recommendations can reduce debugging and rework, highlight likely size-limit issues, and help designers simplify complex components. Use the report throughout authoring to proactively manage component health before activation."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_omnistudio_design_assistant.htm&type=5",connections:[{"planet":"config","desc":"Design Assistant validates against interaction configuration rules"}]},
    {id:"tq-preview",name:"Preview & Debug",icon:"\u{1F50E}",desc:"Preview & Debug capabilities let designers exercise OmniStudio components during development before activation or publication. Omniscript preview supports testing guided interactions, data behavior, and conditional paths, while Flexcard preview and debugging support validation of displayed data and configured interactions. These tools help identify configuration issues in the component’s applicable runtime and interaction configuration context.",tags:["OmniProcess","OmniUiCard"],docs:["Preview an Omniscript to run through its guided process and verify how the component displays, collects, and responds to data. Inspect the runtime Data JSON as the interaction progresses to understand element values and action responses. Exercise different inputs to validate conditional logic and alternate branches before activating the Omniscript.","Preview and debug a Flexcard to verify its contextual data, states, elements, and actions before activation and publication. Use representative runtime context and live data to confirm that conditions produce the intended interface. Perform configured interactions to identify data or behavior issues while the Flexcard remains in development."],connections:[{"planet":"omniscripts","desc":"Preview mode validates OmniScript behavior before activation"},{"planet":"flexcards","desc":"Preview mode tests FlexCard rendering with live data"}]}
  ],
  dataFlow: ["Open the Omniscript or Flexcard configuration in its OmniStudio designer.","Review Design Assistant alerts and refine the component against reported recommendations.","Preview the component with representative data and the applicable interaction configuration context.","Exercise guided paths, conditional behavior, displayed data, and configured actions.","Run UTAM end-to-end tests for the Omniscript or Flexcard before deployment."],
  connections: [{"planet":"omniscripts","desc":"Testing tools validate OmniScript configurations"},{"planet":"flexcards","desc":"Testing tools validate FlexCard configurations"},{"planet":"config","desc":"Testing respects interaction configuration context"}]
},

deployment: {
  packages: ["omnistudio"],
  name: "Deployment & Migration",
  icon: "\u{1F4E6}",
  color: "#94a3b8",
  description: "Deployment & Migration covers packaging, versioning, and moving OmniStudio components across Salesforce environments. DataPacks collect Omniscript, Flexcard, Integration Procedure, and Data Mapper definitions with related functionality for deployment between orgs. For standard runtime with standard objects, Salesforce recommends Salesforce CLI and a development lifecycle that promotes components from development through testing to production. Versioning also enables modification of standard content without editing the Salesforce-maintained Version 1.",
  components: [
    {id:"dp-datapacks",name:"DataPack Export/Import",icon:"\u{1F4E5}",desc:"DataPack Export/Import supports moving collections of OmniStudio components and related functionality between Salesforce environments. DataPacks package Omniscript, Flexcard, Integration Procedure, and Data Mapper definitions for deployment from a sandbox or development org to another org, such as production. For standard runtime with standard objects, Salesforce recommends Salesforce CLI for component export, import, and deployment.",tags:["OmniDataPack"],docs:["An Omni DataPack is a collection of OmniStudio components and related functionality packaged for deployment between orgs. A DataPack can contain Omniscript, Flexcard, Integration Procedure, and Data Mapper definitions. This packaging supports a development lifecycle in which solutions are created in a development org, tested in a test or integration org, and then deployed to production.","The standard designer doesn't provide in-product export and import for Flexcards, Omniscripts, Data Mappers, or Integration Procedures; use Salesforce CLI instead. Salesforce CLI supports these OmniStudio components as well as Salesforce metadata and other Salesforce components. It works with standard objects in the source org and requires standard objects and standard runtime in the target org."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_deploy_or_migrate.htm&type=5",connections:[{"planet":"omniscripts","desc":"DataPacks export OmniScript definitions with all elements"},{"planet":"flexcards","desc":"DataPacks export FlexCard definitions with states and actions"},{"planet":"integration","desc":"DataPacks export Integration Procedure definitions"},{"planet":"datamappers","desc":"DataPacks export Data Mapper definitions"}]},
    {id:"dp-versioning",name:"Version Management",icon:"\u{1F4CB}",desc:"Version Management supports creating editable versions of OmniStudio content while preserving the Salesforce-provided base version. Standard content shipped with a Salesforce Industries license must be versioned before it can be modified. Release updates apply to Version 1, while user-created versions don't receive those updates.",tags:["OmniProcess","OmniUiCard","OmniDataTransformation"],docs:["Version 1 of standard OmniStudio content is never editable, and Salesforce pushes release updates to that version. To modify a standard component, create a separate version in the designer. The created version remains independent and doesn't update when later releases modify Version 1.","When adopting the standard designer directly in sandbox or production environments, Salesforce recommends creating a new version of each OmniStudio component and validating it in the standard designer. Activation determines how Flexcards and Omniscripts are made available at runtime. Existing Flexcard and Omniscript Lightning web components created before standard runtime was enabled use standard runtime after they are deactivated and reactivated."],docUrl:"https://help.salesforce.com/s/articleView?id=xcloud.os_deploy.htm&type=5",connections:[]},
    {id:"dp-dependencies",name:"Dependency Resolution",icon:"\u{1F517}",desc:"Dependency Resolution addresses the related OmniStudio components and Salesforce metadata that must be considered during deployment planning. Deployments can include Omniscripts, Flexcards, Integration Procedures, Data Mappers, and supporting metadata through Salesforce CLI. Tool selection and deployment grouping must account for the source and target data models, runtimes, and Salesforce restrictions on combining setup and non-setup objects.",tags:["OmniDataPack"],docs:["Select a deployment tool according to what is being deployed and the data model and OmniStudio runtime used by the source and target orgs. Salesforce CLI supports Omniscripts, Flexcards, Integration Procedures, Data Mappers, other Salesforce components, and metadata such as FlexiPage, PermissionSet, and OmniStudio Lightning Web Components. Its compatibility is limited to standard objects in the source org and standard objects with standard runtime in the target org.","Separate setup objects from non-setup objects when organizing a deployment because Salesforce doesn't allow them to be deployed together. Setup objects include FlexiPage, Profile, PermissionSet, and CustomField. Non-setup objects include OmniStudio entities such as OmniProcess and OmniUICard."],connections:[]}
  ],
  dataFlow: ["Create or update OmniStudio components in a development org.","Create new component versions where editable variants are required.","Package Omniscript, Flexcard, Integration Procedure, and Data Mapper definitions for deployment.","Separate setup metadata from non-setup OmniStudio entities.","Deploy the components to a test or integration org and validate them.","Deploy the validated components to the production org."],
  connections: [{"planet":"omniscripts","desc":"DataPacks package OmniScript definitions"},{"planet":"flexcards","desc":"DataPacks package FlexCard definitions"},{"planet":"integration","desc":"DataPacks package Integration Procedure definitions"},{"planet":"datamappers","desc":"DataPacks package Data Mapper definitions"}]
}

};
